function showSearch(){
  hub.append(node('h1','','Search'),node('p','hub-lead','Find projects stored in this browser. More sources will be available when they are connected.'));
  const bar=node('div','hub-bar');const input=node('input','hub-search');input.type='search';input.placeholder='Search projects...';input.setAttribute('aria-label','Search projects');bar.append(input);const results=node('div','project-grid');const hint=node('p','hub-hint','Type to search your preview projects.');hub.append(bar,hint,results);
  input.addEventListener('input',()=>{results.replaceChildren();const term=input.value.trim().toLowerCase();if(!term){hint.textContent='Type to search your preview projects.';return}const matches=projectStore.list().filter(p=>(p.name+' '+p.description).toLowerCase().includes(term));hint.textContent=matches.length?matches.length+' project(s) found.':'No projects found.';for(const project of matches){const card=node('button','project-card');card.append(node('span','project-card-icon','▧'),node('h2','',project.name),node('p','',project.description||'No description yet'));card.onclick=()=>{hub.hidden=true;showProjects();showProject(project.id)};results.append(card)}});
}

function inspectorLimits(){const scale=Number.parseFloat(getComputedStyle(document.documentElement).getPropertyValue('--app-scale'))||1;const available=workspaceBody.getBoundingClientRect().width/scale;const overlay=window.matchMedia('(max-width:800px)').matches;const max=Math.max(0,Math.min(1200,available-(overlay?12:220)));return {scale,min:Math.min(240,max),max}}

function applyInspectorWidth(){const limits=inspectorLimits();const actual=Math.max(limits.min,Math.min(limits.max,inspectorDesired));inspector.style.setProperty('--inspector-width',actual+'px');inspectorResize.setAttribute('aria-valuemin',String(Math.round(limits.min)));inspectorResize.setAttribute('aria-valuemax',String(Math.round(limits.max)));inspectorResize.setAttribute('aria-valuenow',String(Math.round(actual)));inspectorResize.setAttribute('aria-valuetext',Math.round(actual)+' pixels wide');return actual}

function saveInspectorWidth(){try{localStorage.setItem('isa.inspector.width',String(Math.round(inspectorDesired)))}catch(error){isaNotifications.show('Could not save the panel width.')}}

function finishInspectorResize(event,cancelled){if(!resizeDrag||event.pointerId!==resizeDrag.pointer)return;if(cancelled)inspectorDesired=resizeDrag.original;else saveInspectorWidth();resizeDrag=null;inspectorResize.classList.remove('dragging');document.body.classList.remove('inspector-resizing');applyInspectorWidth()}

function setInspector(mode){if(inspectorMode===mode)mode=null;inspectorMode=mode;changesSequence++;inspector.hidden=!mode;taskOverviewToggle.classList.toggle('active',mode==='overview');changesToggle.classList.toggle('active',mode==='changes');taskOverviewToggle.setAttribute('aria-expanded',String(mode==='overview'));changesToggle.setAttribute('aria-expanded',String(mode==='changes'));refreshChanges.hidden=mode!=='changes';if(!mode)return;applyInspectorWidth();inspectorTitle.textContent=mode==='overview'?'Task overview':'Changes';if(mode==='overview')renderTaskOverview();else loadChanges()}

function renderTaskOverview(){if(inspectorMode!=='overview')return;inspectorBody.replaceChildren();const chat=chats.find(item=>item.id===activeChatId);if(!chat){inspectorBody.append(node('p','inspector-note','No conversation selected. Start or open a conversation to see its activity.'));return}const userMessages=chat.messages.filter(item=>item.role==='user'),assistantMessages=chat.messages.filter(item=>item.role==='assistant'),lastUser=userMessages.at(-1),lastAssistant=assistantMessages.at(-1),running=pendingChats.has(chat.id);const card=node('section','inspector-card');card.append(node('h3','',chat.title));const badge=node('span','inspector-badge',running?'Waiting for provider':lastAssistant?(lastAssistant.error?'Last response failed':'Response complete'):'No response yet');card.append(badge);const meta=node('div','inspector-meta');meta.append(node('span','',userMessages.length+' user message'+(userMessages.length===1?'':'s')),node('span','',assistantMessages.length+' response'+(assistantMessages.length===1?'':'s')));card.append(meta);inspectorBody.append(card);if(chat.goalPlan){const plan=node('section','inspector-card');plan.append(node('h3','','Goal plan'),node('p','',chat.goalPlan.objective),node('pre','goal-plan-text',chat.goalPlan.text),node('p','inspector-note','Generated plan for review; commands must be entered explicitly.'));const executePlan=node('button','secondary-action','Run explicit plan steps');executePlan.type='button';executePlan.onclick=()=>openGoalRunner(chat.id);plan.append(executePlan);inspectorBody.append(plan)}if(chat.goalError){const error=node('section','inspector-card');error.append(node('h3','','Goal planning failed'),node('p','',chat.goalError));inspectorBody.append(error)}const task=node('section','inspector-card');task.append(node('h3','','Latest request'),node('p','',lastUser?.text||'No request yet.'));inspectorBody.append(task);if(lastAssistant&&!running){const result=node('section','inspector-card');result.append(node('h3','',lastAssistant.error?'Latest error':'Latest response'),node('p','',lastAssistant.text.slice(0,500)+(lastAssistant.text.length>500?'…':'')));inspectorBody.append(result)}inspectorBody.append(node('p','inspector-note','Shows actual chat activity. Detailed pool steps and tool calls are not shown here.'))}

function splitChanges(text){return isaConversationUtils.splitChanges(text)}

function appendDiffSection(label,text){const files=splitChanges(text);if(!files.length)return 0;inspectorBody.append(node('h3','diff-section-title',label+' · '+files.length));for(const file of files.slice(0,200)){const detail=node('details','diff-file'),summary=node('summary'),name=node('span','diff-name',file.path),counts=node('span','diff-counts');name.title=file.path;counts.append(node('span','diff-plus','+'+file.plus),document.createTextNode(' '),node('span','diff-minus','−'+file.minus));summary.append(name,counts);detail.append(summary);detail.addEventListener('toggle',()=>{if(!detail.open||detail.dataset.loaded)return;detail.dataset.loaded='true';const pre=node('pre','diff-content'),fragment=document.createDocumentFragment();for(const line of file.lines.slice(0,2000)){const type=line.startsWith('+')&&!line.startsWith('+++')?'add':line.startsWith('-')&&!line.startsWith('---')?'remove':line.startsWith('@@')?'hunk':'';fragment.append(node('span','diff-line '+type,line||' '))}pre.append(fragment);if(file.lines.length>2000)pre.append(node('span','diff-line diff-truncated','Diff truncated after 2,000 lines.'));detail.append(pre)});inspectorBody.append(detail)}if(files.length>200)inspectorBody.append(node('p','inspector-note','Showing the first 200 files in this section.'));return files.length}

async function loadChanges(){if(inspectorMode!=='changes')return;const token=++changesSequence;inspectorBody.replaceChildren(node('p','inspector-note','Loading Git changes…'));refreshChanges.disabled=true;try{const response=await fetch('/api/changes',{method:'POST',headers:localWorkspaceHeaders(),body:'{}'});const result=await response.json();if(token!==changesSequence||inspectorMode!=='changes')return;if(!response.ok)throw new Error(typeof result.error==='string'?result.error:'Git changes are unavailable.');if(typeof result.staged!=='string'||typeof result.unstaged!=='string')throw new Error('Invalid Git response.');inspectorBody.replaceChildren();inspectorBody.append(node('p','inspector-note','Read-only Git changes in the configured server workspace. Staged and unstaged changes are shown separately; untracked files are not included.'));const count=appendDiffSection('Unstaged',result.unstaged)+appendDiffSection('Staged',result.staged);if(!count)inspectorBody.append(node('p','inspector-note','No tracked Git changes found.'));inspectorBody.append(node('p','inspector-note','Revert and browser-folder integration are not connected yet.'))}catch(error){if(token===changesSequence&&inspectorMode==='changes')inspectorBody.replaceChildren(node('p','inspector-note',error.message||'Could not load Git changes.'))}finally{if(token===changesSequence)refreshChanges.disabled=false}}

function showUtility(title,lines){const dialog=document.querySelector('#helpDialog'),body=document.querySelector('#helpDialogBody');document.querySelector('#helpDialogTitle').textContent=title;body.replaceChildren();for(const line of lines){const paragraph=document.createElement('p');paragraph.textContent=line;body.append(paragraph)}dialog.showModal()}

function showHelpResponse(){
  document.querySelector('#hub').hidden=true;projectsSection.hidden=true;document.querySelector('.composer-wrap').hidden=false;
  if(welcome.hidden===false){thread.replaceChildren();welcome.hidden=true;thread.hidden=false}
  const panel=document.createElement('section');panel.className='help-response';panel.setAttribute('aria-label','Help response');
  const heading=document.createElement('div');heading.className='help-response-head';const icon=document.createElement('span');icon.className='help-response-icon';icon.textContent='?';heading.append(icon,document.createTextNode('Help'));
  const intro=document.createElement('p');intro.textContent='Here are five useful commands to get started:';const list=document.createElement('ul');list.className='help-commands';
  for(const key of ['help','resume-ac','resume-lp','projects','search']){const row=document.createElement('li'),code=document.createElement('code');code.textContent='./'+key+'/.';row.append(code,document.createTextNode('  '+helpDescriptions[key]));list.append(row)}
  const form=document.createElement('form');form.className='help-query';const wrap=document.createElement('div');wrap.className='help-input-wrap';const suggestions=document.createElement('div');suggestions.className='help-suggestions';suggestions.hidden=true;suggestions.setAttribute('role','listbox');suggestions.id='help-options-'+(++helpPanelCounter);const ghost=document.createElement('div');ghost.className='help-ghost';ghost.hidden=true;ghost.setAttribute('aria-hidden','true');const typed=document.createElement('span'),tail=document.createElement('span');ghost.append(typed,tail);const input=document.createElement('input');input.type='text';input.placeholder='Type a command to learn what it does...';input.setAttribute('aria-label','Ask about a command');input.setAttribute('aria-autocomplete','list');input.setAttribute('aria-controls',suggestions.id);input.setAttribute('aria-expanded','false');wrap.append(suggestions,ghost,input);const submit=document.createElement('button');submit.type='submit';submit.textContent='Ask';form.append(wrap,submit);const results=document.createElement('div');results.setAttribute('aria-live','polite');
  let matches=[],chosen=0,start=0;const names=Object.keys(helpDescriptions).sort((a,b)=>a.localeCompare(b));
  function refresh(reset=false){const text=input.value;const active=text.length>0&&!/\s/.test(text)&&!text.startsWith('./')&&input.selectionStart===text.length&&input.selectionEnd===text.length;if(reset){chosen=0;start=0}matches=active?names.filter(name=>name.startsWith(text.toLowerCase())&&name.length>text.length):[];if(chosen>=matches.length)chosen=0;if(chosen<start)start=chosen;if(chosen>=start+5)start=chosen-4;start=Math.max(0,Math.min(start,Math.max(0,matches.length-5)));const selected=matches[chosen];suggestions.hidden=!selected;ghost.hidden=!selected;input.setAttribute('aria-expanded',String(Boolean(selected)));typed.textContent=text;tail.textContent=selected?selected.slice(text.length):'';suggestions.replaceChildren();if(!selected){input.removeAttribute('aria-activedescendant');return}matches.slice(start,start+5).forEach((name,offset)=>{const index=start+offset;const option=document.createElement('button');option.type='button';option.className='help-suggestion';option.id=suggestions.id+'-'+index;option.setAttribute('role','option');option.setAttribute('aria-selected',String(index===chosen));option.textContent=name;option.addEventListener('mousedown',event=>event.preventDefault());option.onclick=()=>{input.value=name;input.focus();input.setSelectionRange(name.length,name.length);refresh(true)};suggestions.append(option)});input.setAttribute('aria-activedescendant',suggestions.id+'-'+chosen)}
  input.addEventListener('input',()=>refresh(true));input.addEventListener('click',()=>refresh());input.addEventListener('focus',()=>refresh());input.addEventListener('blur',()=>{suggestions.hidden=true;ghost.hidden=true;input.setAttribute('aria-expanded','false');input.removeAttribute('aria-activedescendant')});input.addEventListener('keydown',event=>{if(!matches.length||suggestions.hidden)return;if(event.key==='Tab'){event.preventDefault();input.value=matches[chosen];input.setSelectionRange(input.value.length,input.value.length);refresh(true)}else if(event.key==='ArrowDown'||event.key==='ArrowUp'){event.preventDefault();chosen=Math.max(0,Math.min(matches.length-1,chosen+(event.key==='ArrowDown'?1:-1)));refresh()}});
  form.addEventListener('submit',event=>{event.preventDefault();const entered=input.value.trim();if(!entered){input.focus();return}let key=entered.toLowerCase();if(key.startsWith('./')&&key.endsWith('/.'))key=key.slice(2,-2);const result=document.createElement('div');result.className='help-result';const title=document.createElement('strong');title.textContent=entered;const description=document.createElement('p');description.textContent=helpDescriptions[key]||'Command not found. Try a name such as help or projects.';result.append(title,description);results.append(result);input.value='';refresh(true);result.scrollIntoView({block:'nearest',behavior:'smooth'});input.focus()});
  panel.append(heading,intro,list,form,results);thread.append(panel);document.querySelector('#content').scrollTop=document.querySelector('#content').scrollHeight;input.focus();
}

function runChatCommand(text){
  const utility=text.toLowerCase();
  if(utility==='./isabel te amo/.'){
    if(activeChatId&&(pendingChats.has(activeChatId)||activeToolLoops.has(activeChatId))){isaNotifications.show('Wait for the current response before sending another message.');return false}
    const now=new Date().toISOString();
    const message={role:'user',text,at:now};
    const reply={role:'assistant',provider:'local',localKind:'isabel-response',text:isabelResponseText,at:now};
    const existing=chats.find(chat=>chat.id===activeChatId);
    const chat=existing?{...existing,messages:[...existing.messages,message,reply]}:{id:Date.now().toString(36)+'-'+Math.random().toString(36).slice(2),title:text.slice(0,60),messages:[message,reply],settings:draftChatSettings,createdAt:now};
    if(!saveChats([chat,...chats.filter(item=>item.id!==chat.id)]))return false;
    openChat(chat.id);renderActivity();return true;
  }
  if(utility==='./help/.'){showHelpResponse();return true}if(utility==='./resume-ac/.'||utility==='./resume-lp/.'){const all=utility==='./resume-ac/.';showUtility(all?'All-chat summary (AC)':'Last-prompt summary (LP)',[all?'A 200–300 word summary of the overall conversation and project.':'A 100–200 word summary of the latest prompt and response.','No summary is available in this chat: the browser is not yet connected to the Rust session or an AI provider. No chat message was added.']);return true}
  const match=text.match(/^(\.\/[a-z-]+\/\.)(?:\s+(.*))?$/i);if(!match){isaNotifications.show('Invalid command. Use ./command/.');return false}const name=match[1].toLowerCase();if(match[2]){isaNotifications.show('Command arguments are not connected yet.');return false}
  const localTools={'./workspace-info/.':'workspaceInfoButton','./mcp-tools/.':'mcpToolsButton','./tool-loop/.':'toolLoopButton','./chat-mcp/.':'chatMcpButton','./pool-mcp/.':'poolMcpButton','./action-history/.':'actionHistoryButton','./edit-transaction/.':'transactionButton','./undo-transaction/.':'undoTransactionButton','./undo-edit/.':'undoEditButton','./propose-edit/.':'proposeEditButton'};
  if(name==='./sessions/.'){openCliSessionImport();return true}
  if(name==='./semantic-search/.'){openSemanticSearch();return true}
  if(name==='./work/.'){openWorkTracker();return true}
  if(name==='./running-actions/.'){openRunningActions();return true}
  if(name==='./process-snapshot/.'){openProcessSnapshot();return true}
  if(name==='./capabilities/.'){openServerCapabilities();return true}
  if(name==='./local-token/.'){openLocalToken();return true}
  if(localTools[name]){if(!activeChatId){isaNotifications.show('Start a chat before using this command.');return false}document.getElementById(localTools[name]).click();return true}
  const pages={'./agents/.':'Agents','./automations/.':'Automations','./extensions/.':'Extensions','./history/.':'Chats','./knowledge/.':'Knowledge center','./search/.':'Search'};
  if(name==='./projects/.'){showProjects();return true}if(pages[name]){showHub(pages[name]);return true}if(name==='./help/.'){isaNotifications.show('Use ./ followed by a command; Tab completes and arrows navigate.');return true}isaNotifications.show('This command requires the Rust backend and is not connected to chat yet.');return false;
}

function acceptCompletion(){if(!completion)return;promptBox.value=completion;promptBox.setSelectionRange(completion.length,completion.length);selectedCommand=0;updateCompletion();promptBox.focus()}

function updateCompletion(reset=false){
  const text=promptBox.value;
  const atEnd=promptBox.selectionStart===text.length && promptBox.selectionEnd===text.length;
  if(reset){selectedCommand=0;commandWindowStart=0;}
  commandMatches=atEnd && text.startsWith('./') && (!/\s/.test(text) || './isabel te amo/.'.startsWith(text.toLowerCase())) ? commands.filter(command=>command.name.toLowerCase().startsWith(text.toLowerCase())&&command.name.length>text.length) : [];
  if(selectedCommand>=commandMatches.length)selectedCommand=0;
  if(selectedCommand<commandWindowStart)commandWindowStart=selectedCommand;
  if(selectedCommand>=commandWindowStart+5)commandWindowStart=selectedCommand-4;
  commandWindowStart=Math.max(0,Math.min(commandWindowStart,Math.max(0,commandMatches.length-5)));
  completion=commandMatches[selectedCommand]?.name||'';
  completionGhost.hidden=!completion;completionHint.hidden=!completion;commandList.hidden=!completion;
  promptBox.setAttribute('aria-expanded',String(Boolean(completion)));
  document.querySelector('#completionTyped').textContent=text;
  document.querySelector('#completionTail').textContent=completion.slice(text.length);
  completionHint.textContent=completion?'Tab to complete · ↑ ↓ to choose':'';
  commandList.replaceChildren();
  if(completion){
    const header=document.createElement('div');header.className='command-list-header';header.textContent='COMMANDS · '+(selectedCommand+1)+' / '+commandMatches.length;commandList.append(header);
    commandMatches.slice(commandWindowStart,commandWindowStart+5).forEach((command,offset)=>{
      const index=commandWindowStart+offset;
      const option=document.createElement('button');option.type='button';option.className='command-option';option.setAttribute('role','option');option.id='command-option-'+index;option.setAttribute('aria-selected',String(index===selectedCommand));
      const title=document.createElement('span');title.textContent=command.name;const description=document.createElement('small');description.textContent=command.description;option.append(title,description);
      option.addEventListener('mousedown',event=>event.preventDefault());option.addEventListener('click',()=>{selectedCommand=index;completion=command.name;acceptCompletion()});commandList.append(option);
    });
    promptBox.setAttribute('aria-activedescendant','command-option-'+selectedCommand);
  }else promptBox.removeAttribute('aria-activedescendant');
}
